// Mode: Run Once for All Items

function extractRawText(item) {
  return (
    item?.json?.content?.parts?.[0]?.text ??
    item?.json?.candidates?.[0]?.content?.parts?.[0]?.text ??
    item?.json?.response?.candidates?.[0]?.content?.parts?.[0]?.text ??
    item?.json?.data?.candidates?.[0]?.content?.parts?.[0]?.text ??
    item?.json?.text ??
    item?.json?.output ??
    item?.json?.message ??
    item?.json?.result ??
    null
  );
}

function parseFromText(raw) {
  if (!raw || !String(raw).trim()) {
    throw new Error("Texto vazio para parsear JSON.");
  }

  let rawText = String(raw).trim();

  // Remove blocos markdown ```json ... ``` ou ``` ... ```
  rawText = rawText
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  // Caso venha no formato json(...)
  rawText = rawText
    .replace(/^json\s*\(/i, "")
    .replace(/\)\s*$/i, "")
    .trim();

  // Extrai o primeiro objeto JSON { ... }
  const match = rawText.match(/\{[\s\S]*\}/);

  if (!match) {
    throw new Error(
      "Não encontrei um objeto JSON ({ ... }) dentro do texto:\n" + rawText
    );
  }

  let jsonStr = match[0]
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .trim();

  try {
    return JSON.parse(jsonStr);
  } catch (e) {
    throw new Error(
      "Erro no JSON.parse: " + e.message + "\nJSON recebido:\n" + jsonStr
    );
  }
}

function toNumber(value) {
  if (value === null || value === undefined || value === "") return null;

  if (typeof value === "number") {
    return value;
  }

  const valueStr = String(value).trim();

  // Se vier no formato brasileiro: 1.234,56
  if (valueStr.includes(",")) {
    const normalized = valueStr
      .replace(/\./g, "")
      .replace(",", ".");

    const num = Number(normalized);
    return isNaN(num) ? null : num;
  }

  // Se já vier no formato americano: 206.00
  const num = Number(valueStr);
  return isNaN(num) ? null : num;
}

function onlyNumbers(value) {
  if (!value) return null;
  return String(value).replace(/\D/g, "");
}

const out = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const raw = extractRawText(item);

  if (!raw) {
    const keys = Object.keys(item.json || {});

    throw new Error(
      `Não encontrei o texto no item ${i}. Chaves disponíveis em item.json: ${keys.join(", ")}`
    );
  }

  const data = parseFromText(raw);

  out.push({
    json: {
      nome_arquivo: data.nome_arquivo ?? item.json.nome_arquivo ?? null,

      webViewLink: item.json.webViewLink ?? data.webViewLink ?? null,

      data_emissao: data.data_emissao ?? null,

      nota_fiscal: data.nota_fiscal ?? null,

      valor_total: toNumber(
        data.valor_total ??
        data.valor ??
        null
      ),

      razao_social_tomador:
        data.razao_social_tomador ??
        data.razao_social ??
        null,

      cnpj_tomador: onlyNumbers(
        data.cnpj_tomador ??
        data.cnpj ??
        null
      ),

      aliq_pis: toNumber(data.aliq_pis),
      pis: toNumber(data.pis),

      aliq_cofins: toNumber(data.aliq_cofins),
      cofins: toNumber(data.cofins),

      base_csll: toNumber(data.base_csll),
      aliq_csll: toNumber(data.aliq_csll),
      csll: toNumber(data.csll),

      irrf: toNumber(data.irrf),
      iss: toNumber(data.iss),

      natureza_servico:
        data.natureza_servico ??
        data.natureza ??
        null,

      valor_liquido: toNumber(
        data.valor_liquido ??
        data["Valor liquido"] ??
        data["Valor líquido"] ??
        data.valorLiquido ??
        null
      ),

      tem_retencao: data.tem_retencao ?? false,

      tipo_retencao: data.tipo_retencao ?? null,

      total_retido: toNumber(data.total_retido),

      observacao_retencao: data.observacao_retencao ?? null
    }
  });
}

return out;

